//! `calc`: a checked 64-bit signed integer expression evaluator, one expression per line.
//!
//! Evaluation uses an explicit operator stack (shunting-yard), so arbitrarily deep
//! nesting cannot overflow the call stack.

use std::io::{self, Write};

/// Evaluates each non-blank line of `input`, writing its value or `error`.
pub fn run(input: &[u8], out: &mut dyn Write) -> io::Result<()> {
    for line in input.split(|&b| b == b'\n') {
        if line.iter().all(|&b| b == b' ' || b == b'\t') {
            continue;
        }
        match evaluate(line) {
            Some(value) => writeln!(out, "{value}")?,
            None => out.write_all(b"error\n")?,
        }
    }
    Ok(())
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Op {
    Add,
    Sub,
    Mul,
    Div,
    Rem,
    Neg,
    /// An open parenthesis marker on the operator stack.
    Paren,
}

impl Op {
    fn binary(byte: u8) -> Option<Self> {
        Some(match byte {
            b'+' => Self::Add,
            b'-' => Self::Sub,
            b'*' => Self::Mul,
            b'/' => Self::Div,
            b'%' => Self::Rem,
            _ => return None,
        })
    }

    fn precedence(self) -> u8 {
        match self {
            Self::Paren => 0,
            Self::Add | Self::Sub => 1,
            Self::Mul | Self::Div | Self::Rem => 2,
            Self::Neg => 3,
        }
    }
}

/// Evaluates one expression; `None` signals a syntax, division-by-zero or overflow error.
pub fn evaluate(expr: &[u8]) -> Option<i64> {
    let mut values: Vec<i64> = Vec::new();
    let mut ops: Vec<Op> = Vec::new();
    let mut expect_operand = true;
    let mut i = 0;

    while i < expr.len() {
        let byte = expr[i];
        match byte {
            b' ' | b'\t' => {}
            b'0'..=b'9' if expect_operand => {
                let start = i;
                while i + 1 < expr.len() && expr[i + 1].is_ascii_digit() {
                    i += 1;
                }
                values.push(parse_literal(&expr[start..=i])?);
                expect_operand = false;
            }
            b'-' if expect_operand => ops.push(Op::Neg),
            b'(' if expect_operand => ops.push(Op::Paren),
            b')' if !expect_operand => {
                loop {
                    match ops.pop()? {
                        Op::Paren => break,
                        op => apply(op, &mut values)?,
                    }
                }
            }
            _ if !expect_operand => {
                let op = Op::binary(byte)?;
                while let Some(&top) = ops.last() {
                    if top.precedence() < op.precedence() {
                        break;
                    }
                    ops.pop();
                    apply(top, &mut values)?;
                }
                ops.push(op);
                expect_operand = true;
            }
            _ => return None,
        }
        i += 1;
    }

    if expect_operand {
        return None;
    }
    while let Some(op) = ops.pop() {
        if op == Op::Paren {
            return None;
        }
        apply(op, &mut values)?;
    }
    match values[..] {
        [value] => Some(value),
        _ => None,
    }
}

fn parse_literal(digits: &[u8]) -> Option<i64> {
    digits.iter().try_fold(0i64, |acc, &d| {
        acc.checked_mul(10)?.checked_add(i64::from(d - b'0'))
    })
}

fn apply(op: Op, values: &mut Vec<i64>) -> Option<()> {
    let rhs = values.pop()?;
    let result = if op == Op::Neg {
        rhs.checked_neg()?
    } else {
        let lhs = values.pop()?;
        match op {
            Op::Add => lhs.checked_add(rhs)?,
            Op::Sub => lhs.checked_sub(rhs)?,
            Op::Mul => lhs.checked_mul(rhs)?,
            Op::Div => lhs.checked_div(rhs)?,
            // MIN % -1 is mathematically 0; only a zero divisor is an error.
            Op::Rem if rhs == 0 => return None,
            Op::Rem => lhs.wrapping_rem(rhs),
            Op::Neg | Op::Paren => unreachable!("not a binary operator"),
        }
    };
    values.push(result);
    Some(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn eval(s: &str) -> Option<i64> {
        evaluate(s.as_bytes())
    }

    #[test]
    fn arithmetic_and_precedence() {
        assert_eq!(eval("1 + 2 * 3"), Some(7));
        assert_eq!(eval("(1 + 2) * 3"), Some(9));
        assert_eq!(eval("1 + 2 * 3 - 4 / 2 % 3"), Some(5));
        assert_eq!(eval("10 - 4 - 3"), Some(3));
        assert_eq!(eval("2*(3+4)*5"), Some(70));
        assert_eq!(eval("100 / 10 / 5"), Some(2));
    }

    #[test]
    fn division_semantics() {
        assert_eq!(eval("-7 / 2"), Some(-3));
        assert_eq!(eval("-7 % 3"), Some(-1));
        assert_eq!(eval("7 % -3"), Some(1));
        assert_eq!(eval("1 / 0"), None);
        assert_eq!(eval("5 % 0"), None);
        assert_eq!(eval("(-9223372036854775807 - 1) % -1"), Some(0));
        assert_eq!(eval("(-9223372036854775807 - 1) / -1"), None);
    }

    #[test]
    fn unary_minus() {
        assert_eq!(eval("--5"), Some(5));
        assert_eq!(eval("2 * -3"), Some(-6));
        assert_eq!(eval("1 - -2"), Some(3));
        assert_eq!(eval("-(2 + 3)"), Some(-5));
        assert_eq!(eval("- 2 * 3"), Some(-6));
        assert_eq!(eval("-9223372036854775808"), None);
        assert_eq!(eval("-9223372036854775807 - 1"), Some(i64::MIN));
    }

    #[test]
    fn overflow() {
        assert_eq!(eval("9223372036854775807 + 1"), None);
        assert_eq!(eval("9223372036854775808"), None);
        assert_eq!(eval("3037000500 * 3037000500"), None);
        assert_eq!(eval("0009223372036854775807"), Some(i64::MAX));
    }

    #[test]
    fn syntax_errors() {
        for s in ["1 +", "abc", "()", "1 2", "+1", "(1 + 2", "1 + 2)", ")(", "1 - ", "1 ** 2", "1 2 + 3", "1\r"] {
            assert_eq!(eval(s), None, "{s:?}");
        }
    }

    #[test]
    fn deep_nesting() {
        let depth = 1_000_000;
        let expr = format!("{}1{}", "(".repeat(depth), ")".repeat(depth));
        assert_eq!(eval(&expr), Some(1));
        assert_eq!(eval(&format!("{}1", "-".repeat(depth + 1))), Some(-1));
    }

    #[test]
    fn blank_lines_skipped() {
        let mut out = Vec::new();
        run(b"\n  42  \n\t\n1+1\n", &mut out).unwrap();
        assert_eq!(out, b"42\n2\n");
    }
}

//! `lru`: an LRU cache simulator driven by `SET` / `GET` / `DEL` / `SIZE` commands.

use std::collections::HashMap;
use std::io::{self, Write};

/// Runs the command script in `input`: a capacity line followed by one command per line.
pub fn run(input: &[u8], out: &mut dyn Write) -> io::Result<()> {
    let mut lines = input
        .split(|&b| b == b'\n')
        .map(|line| line.strip_suffix(b"\r").unwrap_or(line));
    let capacity = lines
        .next()
        .and_then(|line| std::str::from_utf8(line).ok())
        .and_then(|s| s.trim().parse::<usize>().ok())
        .filter(|&c| c >= 1)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "invalid capacity line"))?;

    let mut cache = LruCache::new(capacity);
    for line in lines {
        let mut tokens = line.split(|&b| b == b' ');
        match (tokens.next(), tokens.next(), tokens.next()) {
            (Some(b"SET"), Some(key), Some(value)) => cache.set(key, value),
            (Some(b"GET"), Some(key), _) => {
                out.write_all(cache.get(key).unwrap_or(b"NULL"))?;
                out.write_all(b"\n")?;
            }
            (Some(b"DEL"), Some(key), _) => {
                out.write_all(if cache.remove(key) { b"1\n" } else { b"0\n" })?;
            }
            (Some(b"SIZE"), _, _) => writeln!(out, "{}", cache.len())?,
            _ => {} // Blank or malformed line: ignored.
        }
    }
    Ok(())
}

const NIL: u32 = u32::MAX;

struct Node {
    key: Box<[u8]>,
    value: Vec<u8>,
    prev: u32,
    next: u32,
}

/// A fixed-capacity LRU cache: a hash map into a slab-allocated doubly linked list.
/// `head` is the most recently used entry, `tail` the least.
struct LruCache {
    capacity: usize,
    index: HashMap<Box<[u8]>, u32>,
    nodes: Vec<Node>,
    free: Vec<u32>,
    head: u32,
    tail: u32,
}

impl LruCache {
    fn new(capacity: usize) -> Self {
        let reserve = capacity.min(1 << 16);
        Self {
            capacity,
            index: HashMap::with_capacity(reserve),
            nodes: Vec::with_capacity(reserve),
            free: Vec::new(),
            head: NIL,
            tail: NIL,
        }
    }

    fn len(&self) -> usize {
        self.index.len()
    }

    fn get(&mut self, key: &[u8]) -> Option<&[u8]> {
        let id = *self.index.get(key)?;
        self.move_to_front(id);
        Some(&self.nodes[id as usize].value)
    }

    fn set(&mut self, key: &[u8], value: &[u8]) {
        if let Some(&id) = self.index.get(key) {
            let node = &mut self.nodes[id as usize];
            node.value.clear();
            node.value.extend_from_slice(value);
            self.move_to_front(id);
            return;
        }
        let key: Box<[u8]> = key.into();
        let node = Node {
            key: key.clone(),
            value: value.to_vec(),
            prev: NIL,
            next: NIL,
        };
        let id = if let Some(id) = self.free.pop() {
            self.nodes[id as usize] = node;
            id
        } else {
            let id = u32::try_from(self.nodes.len()).expect("cache slab exceeds u32 indices");
            self.nodes.push(node);
            id
        };
        self.index.insert(key, id);
        self.push_front(id);
        if self.index.len() > self.capacity {
            let lru = self.tail;
            let evicted = std::mem::take(&mut self.nodes[lru as usize].key);
            self.index.remove(&evicted);
            self.release(lru);
        }
    }

    fn remove(&mut self, key: &[u8]) -> bool {
        match self.index.remove(key) {
            Some(id) => {
                self.release(id);
                true
            }
            None => false,
        }
    }

    /// Unlinks a node whose key is already gone from the index and recycles its slot.
    fn release(&mut self, id: u32) {
        self.unlink(id);
        let node = &mut self.nodes[id as usize];
        node.key = Box::default();
        node.value = Vec::new();
        self.free.push(id);
    }

    fn move_to_front(&mut self, id: u32) {
        if self.head != id {
            self.unlink(id);
            self.push_front(id);
        }
    }

    fn push_front(&mut self, id: u32) {
        let old_head = self.head;
        {
            let node = &mut self.nodes[id as usize];
            node.prev = NIL;
            node.next = old_head;
        }
        match old_head {
            NIL => self.tail = id,
            h => self.nodes[h as usize].prev = id,
        }
        self.head = id;
    }

    fn unlink(&mut self, id: u32) {
        let Node { prev, next, .. } = self.nodes[id as usize];
        match prev {
            NIL => self.head = next,
            p => self.nodes[p as usize].next = next,
        }
        match next {
            NIL => self.tail = prev,
            n => self.nodes[n as usize].prev = prev,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn render(input: &str) -> String {
        let mut out = Vec::new();
        run(input.as_bytes(), &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        assert_eq!(render("2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n"), "1\nNULL\n2\n");
    }

    #[test]
    fn overwrite_refreshes() {
        assert_eq!(
            render("2\nSET a 1\nSET b 2\nSET a 9\nSET c 3\nGET a\nGET b\nGET c"),
            "9\nNULL\n3\n"
        );
    }

    #[test]
    fn delete_and_reuse_slots() {
        assert_eq!(
            render("2\nSET x 1\nDEL x\nDEL x\nSIZE\nGET x\nSET y 2\nSET z 3\nSET w 4\nGET y\nGET w\nSIZE\n"),
            "1\n0\n0\nNULL\nNULL\n4\n2\n"
        );
    }
}

//! `suite`: a command-line program with three independent subcommands.

mod calc;
mod lru;
mod wordfreq;

use std::io::{self, BufWriter, Read, Write};
use std::process::ExitCode;

type Command = fn(&[u8], &mut dyn Write) -> io::Result<()>;

fn main() -> ExitCode {
    let Some(name) = std::env::args().nth(1) else {
        return usage();
    };
    let command: Command = match name.as_str() {
        "wordfreq" => wordfreq::run,
        "lru" => lru::run,
        "calc" => calc::run,
        _ => return usage(),
    };
    match execute(command) {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) if err.kind() == io::ErrorKind::BrokenPipe => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("app {name}: {err}");
            ExitCode::FAILURE
        }
    }
}

fn execute(command: Command) -> io::Result<()> {
    let mut input = Vec::new();
    io::stdin().lock().read_to_end(&mut input)?;
    let mut out = BufWriter::with_capacity(1 << 16, io::stdout().lock());
    command(&input, &mut out)?;
    out.flush()
}

fn usage() -> ExitCode {
    eprintln!("usage: app <wordfreq|lru|calc>  (reads standard input)");
    ExitCode::from(2)
}

//! `wordfreq`: the ten most frequent ASCII-letter words, case-insensitive.

use std::collections::HashMap;
use std::hash::{BuildHasherDefault, Hasher};
use std::io::{self, Write};

const TOP: usize = 10;

/// Counts words in `input` and writes the most frequent ones as `<count> <word>` lines.
pub fn run(input: &[u8], out: &mut dyn Write) -> io::Result<()> {
    let lowered = input.to_ascii_lowercase();
    for (word, count) in top_words(&count_words(&lowered), TOP) {
        out.write_all(count.to_string().as_bytes())?;
        out.write_all(b" ")?;
        out.write_all(word)?;
        out.write_all(b"\n")?;
    }
    Ok(())
}

type Counts<'a> = HashMap<&'a [u8], u64, BuildHasherDefault<FnvHasher>>;

/// Counts maximal runs of ASCII letters. `text` must already be lowercase.
fn count_words(text: &[u8]) -> Counts<'_> {
    let mut counts = Counts::default();
    for word in text
        .split(|b| !b.is_ascii_alphabetic())
        .filter(|w| !w.is_empty())
    {
        *counts.entry(word).or_insert(0) += 1;
    }
    counts
}

/// Returns up to `n` entries ordered by count descending, then word ascending.
fn top_words<'a>(counts: &Counts<'a>, n: usize) -> Vec<(&'a [u8], u64)> {
    let mut entries: Vec<(&[u8], u64)> = counts.iter().map(|(&w, &c)| (w, c)).collect();
    let order = |a: &(&[u8], u64), b: &(&[u8], u64)| b.1.cmp(&a.1).then_with(|| a.0.cmp(b.0));
    if entries.len() > n {
        entries.select_nth_unstable_by(n, order);
        entries.truncate(n);
    }
    entries.sort_unstable_by(order);
    entries
}

/// 64-bit FNV-1a: fast for the short keys counted here.
struct FnvHasher(u64);

impl Default for FnvHasher {
    fn default() -> Self {
        Self(0xcbf2_9ce4_8422_2325)
    }
}

impl Hasher for FnvHasher {
    fn write(&mut self, bytes: &[u8]) {
        for &b in bytes {
            self.0 ^= u64::from(b);
            self.0 = self.0.wrapping_mul(0x0100_0000_01b3);
        }
    }

    fn finish(&self) -> u64 {
        self.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn render(input: &[u8]) -> String {
        let mut out = Vec::new();
        run(input, &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        assert_eq!(render(b"The cat and the hat."), "2 the\n1 and\n1 cat\n1 hat\n");
    }

    #[test]
    fn separators_and_invalid_utf8() {
        assert_eq!(render(b"don't\xffstop_me 4now\xc3(NOW"), "2 now\n1 don\n1 me\n1 stop\n1 t\n");
    }

    #[test]
    fn empty_input() {
        assert_eq!(render(b"123 !!"), "");
    }

    #[test]
    fn at_most_ten() {
        let text = "a b c d e f g h i j k l a";
        assert_eq!(render(text.as_bytes()).lines().count(), 10);
        assert!(render(text.as_bytes()).starts_with("2 a\n1 b\n"));
    }
}
